`timescale 1ns / 1ps
// Autonomous Self-Checking Testbench generated by RTL-AutoBench
// Reset Configuration: rst (active_high)
module param_counter_autobench_tb;

  // Clocks and Resets
  logic clk;
  logic rst;

  // Input Stimulus Signals
  logic en;
  logic up_down;

  // Monitored Output Signals
  logic [7:0] count;
  logic overflow;

  // Device Under Test (DUT) Instance
  param_counter dut (
    .clk(clk),
    .rst(rst),
    .en(en),
    .up_down(up_down),
    .count(count),
    .overflow(overflow)
  );

  // Free-running Clock: 100MHz (10ns period)
  initial begin
    clk = 0;
    forever #5 clk = ~clk;
  end

  // Scoreboard Verification Registers
  integer errors = 0;
  integer test_vectors = 0;
  integer cycle_count = 0;

  // Autonomous Constrained-Random Stimulus Engine
  initial begin
    // 1. Initial State & Reset Protocol (active_high)
    rst = 1; // Assert Active-High Reset
    en = 0;
    up_down = 0;
    #20; // Hold reset for 2 full clock cycles
    @(negedge clk);
    rst = 0; // Deassert Active-High Reset
    $display("[%0t] [INIT] Reset released (active_high). Beginning autonomous test vectors...", $time);

    // 2. Randomized Fuzzing & Boundary Vector Execution
    repeat (5000) begin
      @(negedge clk);
      en = $urandom_range(0, 1);
      up_down = $urandom_range(0, 1);
      test_vectors = test_vectors + 1;
      @(posedge clk);
      #1;
      // Automated sanity checks (detecting X / Z floating hazards)
      if ($isunknown(count)) begin
        $display("[%0t] [ERROR] Unknown signal state (X/Z) detected on count", $time);
        errors = errors + 1;
      end
      if ($isunknown(overflow)) begin
        $display("[%0t] [ERROR] Unknown signal state (X/Z) detected on overflow", $time);
        errors = errors + 1;
      end
    end

    // 3. Verification Scoreboard Summary
    #20;
    $display("\n==================================================");
    $display("  RTL-AutoBench Verification Scoreboard: param_counter");
    $display("==================================================");
    $display("  Total Test Vectors Evaluated : %0d", test_vectors);
    $display("  Protocol / Assertion Failures: %0d", errors);
    if (errors == 0) begin
      $display("  OVERALL RESULT               : [VERIFICATION PASSED]");
    end else begin
      $display("  OVERALL RESULT               : [VERIFICATION FAILED]");
    end
    $display("==================================================\n");
    $finish;
  end

endmodule
